/**
 * One fixed cover per Life Vision mix type. They do not follow the theme, so
 * a member's Sleep mix always looks like their Sleep mix. Generated by
 * scripts/audio/mix-covers.ts.
 */

export type MixType = 'voice-only' | 'power' | 'meditation' | 'sleep' | 'personal'

const BASE = 'https://media.vibrationfit.com/site-assets/audio/mix-covers'

export const MIX_COVERS: Record<MixType, string> = {
  'voice-only': `${BASE}/voice-only-v1.jpg`,
  power: `${BASE}/power-v1.jpg`,
  meditation: `${BASE}/meditation-v1.jpg`,
  sleep: `${BASE}/sleep-v1.jpg`,
  personal: `${BASE}/personal-v1.jpg`,
}

/** The studio's mix types from the voice / background split (same rules as /audio/mix). */
export function mixTypeFor(variant: string | null | undefined, voice: number | null | undefined, background: number | null | undefined): MixType {
  if (variant === 'personal') return 'personal'
  if (variant === 'standard' || !background) return 'voice-only'
  const v = voice ?? 100
  if (v <= 30) return 'sleep'
  if (v >= 40 && v <= 60) return 'meditation'
  return 'power'
}
